  "schema_version": 1,
  "observations": [
    {
      "key": "obs_quicksort_def",
      "facet": "mechanism",
      "statement": "Quicksort picks a pivot element, partitions remaining elements into those greater than and less than the pivot, and recursively sorts the partitions.",
      "start_line": 4,
      "end_line": 9
    },
    {
      "key": "obs_quicksort_variants",
      "facet": "other",
      "statement": "Variants of quicksort exist for pivot selection, array partitioning, stopping recursion, or switching algorithms for small partitions.",
      "start_line": 9,
      "end_line": 9
    },
    {
      "key": "obs_quicksort_inplace",
      "facet": "property",
      "statement": "Quicksort is a generalization of in-place sort.",
      "start_line": 10,
      "end_line": 12
    },
    {
      "key": "obs_quicksort_las_vegas",
      "facet": "property",
      "statement": "Quicksort is a Las Vegas algorithm when the pivot is picked randomly.",
      "start_line": 14,
      "end_line": 15
    },
    {
      "key": "obs_quicksort_specializations",
      "facet": "relation",
      "statement": "Balanced quicksort, multikey Quicksort, and introspective sort are specializations of quicksort.",
      "start_line": 16,
      "end_line": 23
    },
    {
      "key": "obs_quicksort_aggregate_parent",
      "facet": "relation",
      "statement": "Quicksort is a part of or used in q sort.",
      "start_line": 24,
      "end_line": 27
    },
    {
      "key": "obs_quicksort_aggregate_child",
      "facet": "relation",
      "statement": "Partition, divide and conquer, recursion, Select, and sublinear time algorithm are parts of or used in quicksort.",
      "start_line": 28,
      "end_line": 39
    },
    {
      "key": "obs_quicksort_see_also",
      "facet": "reference",
      "statement": "External quicksort and dual-pivot quicksort are related topics.",
      "start_line": 40,
      "end_line": 44
    },
    {
      "key": "obs_quicksort_worst_case",
      "facet": "property",
      "statement": "Quicksort has a worst-case running time of Θ(n²).",
      "start_line": 46,
      "end_line": 49
    },
    {
      "key": "obs_quicksort_typical_case",
      "facet": "property",
      "statement": "Quicksort typically has a running time of O(n log n).",
      "start_line": 50,
      "end_line": 52
    },
    {
      "key": "obs_quicksort_practical_performance",
      "facet": "property",
      "statement": "In practical situations, a finely tuned implementation of quicksort beats most sort algorithms, including those with O(n log n) worst-case complexity.",
      "start_line": 52,
      "end_line": 52
    },
    {
      "key": "obs_select_pivot_variant",
      "facet": "mechanism",
      "statement": "Using Select to always pick good pivots creates a quicksort variant with O(n log n) worst-case running time.",
      "start_line": 53,
      "end_line": 56
    },
    {
      "key": "obs_dual_pivot_speed",
      "facet": "property",
      "statement": "Dual-pivot quicksort is faster because it accesses less memory.",
      "start_line": 57,
      "end_line": 59
    },
    {
      "key": "obs_references",
      "facet": "reference",
      "statement": "References include Wikipedia entry, Java/C++ explanations, Flower Brackets explanation, and comparisons with heapsort, merge sort, and bubble sort.",
      "start_line": 62,
      "end_line": 85
    },
    {
      "key": "obs_source_citation",
      "facet": "reference",
      "statement": "Source is Dictionary of Algorithms and Data Structures, edited by Paul E. Black, entry by Conrado Martinez, modified 6 April 2023.",
      "start_line": 96,
      "end_line": 101
    }
  ],
  "claims": [
    {
      "key": "claim_select_improves_worst_case",
      "status": "DERIVED_INTERPRETATION",
