        "obs_quicksort_worst_case",
        "obs_select_pivot_variant"
      ],
      "statement": "The standard quicksort worst-case complexity of Θ(n²) can be improved to O(n log n) by using the Select algorithm for pivot selection."
    },
    {
      "key": "claim_dual_pivot_mechanism",
      "status": "DERIVED_INTERPRETATION",
      "supported_by": [
        "obs_dual_pivot_speed"
      ],
      "statement": "The performance advantage of dual-pivot quicksort over standard quicksort is attributed to reduced memory access."
    }
  ],
